package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PatternKey;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbFilterSelectivityStatsEvidencePolicyTest {

	@Test
	void snapshotOnlyConstructionDoesNotInspectAdaptiveSidecarIdentity(@TempDir Path dataDir) throws Exception {
		Path estimatorPath = dataDir.resolve("join-estimator.rjes");
		Files.write(estimatorPath.resolveSibling("join-estimator.rjes.filters"), new byte[] { 0, 0, 0, 7 });
		AtomicInteger identityReads = new AtomicInteger();

		new LmdbFilterSelectivityStats(estimatorPath, mock(TripleStore.class), mock(ValueStore.class), false, 0L, 0,
				false, () -> {
					identityReads.incrementAndGet();
					return null;
				}, 0, () -> false);

		assertEquals(0, identityReads.get(), "Snapshot-only construction must not inspect adaptive sidecar identity.");
	}

	@Test
	void adaptiveEvidencePolicyIsCapturedForTheStoreLifetime(@TempDir Path dataDir) {
		AtomicBoolean adaptiveEvidenceAllowed = new AtomicBoolean(false);
		LmdbFilterSelectivityStats stats = stats(dataDir, mock(TripleStore.class), adaptiveEvidenceAllowed);
		PatternKey key = new PatternKey(SimpleValueFactory.getInstance().createIRI("urn:test:predicate"), 0);

		adaptiveEvidenceAllowed.set(true);
		stats.recordFilterOutcome(key, "BOUND(?value)", 1L, 1L);

		assertEquals(-1.0d, stats.getFilterPassRatio(key, "BOUND(?value)"),
				"A store opened snapshot-only must not begin using adaptive evidence later in its lifetime.");
	}

	@Test
	void pendingBackgroundRequestsReportThePhysicalQueue(@TempDir Path dataDir) throws Exception {
		AtomicBoolean adaptiveEvidenceAllowed = new AtomicBoolean(true);
		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.cardinality(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(100.0d);
		LmdbFilterSelectivityStats stats = stats(dataDir, tripleStore, adaptiveEvidenceAllowed);
		StatementPattern pattern = new StatementPattern(new Var("subject"), new Var("predicate"), new Var("value"));
		Filter filter = new Filter(pattern.clone(), new Bound(new Var("value")));

		stats.estimateLiveFilterPass(filter, pattern);
		assertEquals(1, stats.pendingBackgroundSamplingRequests());

		adaptiveEvidenceAllowed.set(false);
		assertEquals(1, stats.pendingBackgroundSamplingRequests(),
				"Queue diagnostics must report physical work rather than a policy-filtered zero.");
	}

	private static LmdbFilterSelectivityStats stats(Path dataDir, TripleStore tripleStore,
			AtomicBoolean adaptiveEvidenceAllowed) {
		return new LmdbFilterSelectivityStats(dataDir.resolve("join-estimator.rjes"), tripleStore,
				mock(ValueStore.class), false, 1_000L, 4_096, true, () -> null, 0,
				adaptiveEvidenceAllowed::get);
	}
}
